// Builds src/pos/portal-embed.css from src/styles.css: the portal stylesheet scoped to
// .portal-embed, so portal pages shown inside the POS keep their look without changing
// the POS itself. Runs before every build (see package.json); do not edit the output.
import { readFileSync, writeFileSync } from 'node:fs'

const src = readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '')

// Split into top-level statements / blocks by brace depth.
const parts = []
let depth = 0, start = 0, paren = 0
for (let i = 0; i < src.length; i++) {
  const ch = src[i]
  if (ch === '(') paren++
  else if (ch === ')') paren--
  else if (paren > 0) continue // e.g. the ';' inside url(...wght@400;700...)
  else if (ch === '{') depth++
  else if (ch === '}') { depth--; if (depth === 0) { parts.push(src.slice(start, i + 1).trim()); start = i + 1 } }
  else if (ch === ';' && depth === 0) { parts.push(src.slice(start, i + 1).trim()); start = i + 1 }
}

const top = [], scoped = []
for (const part of parts) {
  if (!part) continue
  if (/^@import/.test(part)) top.push(part) // fonts
  else if (/^@(-webkit-)?keyframes|^@font-face/.test(part)) top.push(part)
  else if (/^:root\s*\{/.test(part)) scoped.push(part.replace(/^:root/, '&')) // variables on .portal-embed
  else if (/^(html|body|#root)(\s*,\s*(html|body|#root))*\s*\{/.test(part)) scoped.push(part.replace(/^[^{]+/, '& ')) // page base -> container
  else {
    scoped.push(part)
    // The item picker list is attached to <body> (outside .portal-embed): keep its rules global too.
    if (/^.item-picker/.test(part)) top.push(part)
  }
}

scoped.push('& { min-height: 0; overflow-x: visible; background: transparent; }') // sits inside the POS page
const out = `/* GENERATED by scripts/embed-css.mjs from src/styles.css. Do not edit. */\n${top.join('\n')}\n.portal-embed {\n${scoped.join('\n')}\n}\n`
writeFileSync(new URL('../src/pos/portal-embed.css', import.meta.url), out)
console.log(`portal-embed.css: ${scoped.length} scoped rules`)
